#include "2mm.h"

extern "C" {
void kernel_2mm(
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;

  int i, j, k;

  // Local on-chip buffers to avoid serialized AXI accesses
  static double A_buf[NI][NK];
  static double B_buf[NK][NJ];
  static double C_buf[NJ][NL];
  static double tmp_buf[NI][NJ];
  static double D_buf[NI][NL];
#pragma HLS ARRAY_PARTITION variable=A_buf cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=B_buf cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=C_buf cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=tmp_buf cyclic factor=8 dim=2

  // ---- Load inputs ----
  LOAD_A_I: for (i = 0; i < ni; i++)
    LOAD_A_K: for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      A_buf[i][k] = A[i][k];
    }

  LOAD_B_K: for (k = 0; k < nk; k++)
    LOAD_B_J: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      B_buf[k][j] = B[k][j];
    }

  LOAD_C_J: for (j = 0; j < nj; j++)
    LOAD_C_L: for (k = 0; k < nl; k++) {
#pragma HLS PIPELINE II=1
      C_buf[j][k] = C[j][k];
    }

  LOAD_D_I: for (i = 0; i < ni; i++)
    LOAD_D_L: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      D_buf[i][j] = D[i][j];
    }

  // ---- First matmul: tmp = alpha * A * B ----
  // Break the FP accumulation dependency using partial sums over partitioned k.
  M1_I: for (i = 0; i < ni; i++) {
    M1_J: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      const int PS = 8;
      double acc[PS];
#pragma HLS ARRAY_PARTITION variable=acc complete dim=1
    INIT_PS1: for (int p = 0; p < PS; p++) {
#pragma HLS UNROLL
        acc[p] = 0.0;
      }
    M1_K: for (k = 0; k < nk; k++) {
#pragma HLS UNROLL factor=8
        acc[k % PS] += alpha * A_buf[i][k] * B_buf[k][j];
      }
      double s = 0.0;
    RED_PS1: for (int p = 0; p < PS; p++) {
#pragma HLS UNROLL
        s += acc[p];
      }
      tmp_buf[i][j] = s;
    }
  }

  // ---- Second matmul: D = beta*D + tmp * C ----
  M2_I: for (i = 0; i < ni; i++) {
    M2_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      const int PS = 8;
      double acc[PS];
#pragma HLS ARRAY_PARTITION variable=acc complete dim=1
    INIT_PS2: for (int p = 0; p < PS; p++) {
#pragma HLS UNROLL
        acc[p] = 0.0;
      }
    M2_K: for (k = 0; k < nj; k++) {
#pragma HLS UNROLL factor=8
        acc[k % PS] += tmp_buf[i][k] * C_buf[k][j];
      }
      double s = D_buf[i][j] * beta;
    RED_PS2: for (int p = 0; p < PS; p++) {
#pragma HLS UNROLL
        s += acc[p];
      }
      D_buf[i][j] = s;
    }
  }

  // ---- Store outputs ----
  STORE_TMP_I: for (i = 0; i < ni; i++)
    STORE_TMP_J: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      tmp[i][j] = tmp_buf[i][j];
    }

  STORE_D_I: for (i = 0; i < ni; i++)
    STORE_D_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      D[i][j] = D_buf[i][j];
    }
}
}
