#include "3mm.h"

extern "C" {
void kernel_3mm(
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6

#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

  int i, j, k;

  // Local on-chip buffers to allow parallel access patterns.
  static double Abuf[NI][NK];
  static double Bbuf[NK][NJ];
  static double Cbuf[NJ][NM];
  static double Dbuf[NM][NL];
  static double Ebuf[NI][NJ];
  static double Fbuf[NJ][NL];
  static double Gbuf[NI][NL];

  // Partition along the reduction dimension so the unrolled k-loop
  // can read all operands in parallel.
#pragma HLS ARRAY_PARTITION variable=Abuf complete dim=2
#pragma HLS ARRAY_PARTITION variable=Bbuf complete dim=1
#pragma HLS ARRAY_PARTITION variable=Cbuf complete dim=2
#pragma HLS ARRAY_PARTITION variable=Dbuf complete dim=1
#pragma HLS ARRAY_PARTITION variable=Ebuf complete dim=2
#pragma HLS ARRAY_PARTITION variable=Fbuf complete dim=1

  // ---- Load inputs into local buffers ----
  LD_A_I: for (i = 0; i < ni; i++)
    LD_A_K: for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      Abuf[i][k] = A[i][k];
    }
  LD_B_I: for (i = 0; i < nk; i++)
    LD_B_J: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      Bbuf[i][j] = B[i][j];
    }
  LD_C_I: for (i = 0; i < nj; i++)
    LD_C_K: for (k = 0; k < nm; k++) {
#pragma HLS PIPELINE II=1
      Cbuf[i][k] = C[i][k];
    }
  LD_D_I: for (i = 0; i < nm; i++)
    LD_D_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      Dbuf[i][j] = D[i][j];
    }

  // ---- E = A * B ----
  E_I: for (i = 0; i < ni; i++)
    E_J: for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE II=1
        double acc = 0.0;
        E_K: for (k = 0; k < nk; ++k) {
#pragma HLS UNROLL
          acc += Abuf[i][k] * Bbuf[k][j];
        }
        Ebuf[i][j] = acc;
      }

  // ---- F = C * D ----
  F_I: for (i = 0; i < nj; i++)
    F_J: for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
        double acc = 0.0;
        F_K: for (k = 0; k < nm; ++k) {
#pragma HLS UNROLL
          acc += Cbuf[i][k] * Dbuf[k][j];
        }
        Fbuf[i][j] = acc;
      }

  // ---- G = E * F ----
  G_I: for (i = 0; i < ni; i++)
    G_J: for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE II=1
        double acc = 0.0;
        G_K: for (k = 0; k < nj; ++k) {
#pragma HLS UNROLL
          acc += Ebuf[i][k] * Fbuf[k][j];
        }
        Gbuf[i][j] = acc;
      }

  // ---- Store results back to global memory ----
  ST_E_I: for (i = 0; i < ni; i++)
    ST_E_J: for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      E[i][j] = Ebuf[i][j];
    }
  ST_F_I: for (i = 0; i < nj; i++)
    ST_F_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      F[i][j] = Fbuf[i][j];
    }
  ST_G_I: for (i = 0; i < ni; i++)
    ST_G_J: for (j = 0; j < nl; j++) {
#pragma HLS PIPELINE II=1
      G[i][j] = Gbuf[i][j];
    }
}
}
