#include "atax.h"

extern "C" {
void kernel_atax(
		 double A[ M + 0][N + 0],
		 double x[ N + 0],
		 double y[ N + 0],
		 double tmp[ M + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

  int i, j;

  // Local on-chip buffers
  double x_local[N];
  double y_local[N];
  double tmp_local_buf[M];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=y_local cyclic factor=8 dim=1

  // Load x into local memory and initialize y_local
  load_x:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    x_local[i] = x[i];
    y_local[i] = 0.0;
  }

  outer:
  for (i = 0; i < m; i++)
    {
      // Partial-sum accumulators to break FP carried dependency
      const int NACC = 8;
      double acc[8];
#pragma HLS ARRAY_PARTITION variable=acc complete dim=1
    init_acc:
      for (int a = 0; a < NACC; a++) {
#pragma HLS UNROLL
        acc[a] = 0.0;
      }

      compute_tmp:
      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        acc[j & (NACC - 1)] += A[i][j] * x_local[j];
      }

      double tmp_val = 0.0;
    reduce_acc:
      for (int a = 0; a < NACC; a++) {
#pragma HLS UNROLL
        tmp_val += acc[a];
      }
      tmp_local_buf[i] = tmp_val;

      update_y:
      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
        y_local[j] = y_local[j] + A[i][j] * tmp_val;
      }
    }

  // Write results back to global memory
  store_y:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    y[i] = y_local[i];
  }

  store_tmp:
  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
    tmp[i] = tmp_local_buf[i];
  }

}
}
