#include "bicg.h"

extern "C" {
void kernel_bicg(
		 double A[N + 0][M + 0],
		 double s[M + 0],
		 double q[N + 0],
		 double p[M + 0],
		 double r[N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=s offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=q offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=p offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=s bundle=control
#pragma HLS INTERFACE s_axilite port=q bundle=control
#pragma HLS INTERFACE s_axilite port=p bundle=control
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j;

  // Local on-chip buffers to avoid m_axi carried dependence on s[j]
  double s_local[M];
  double p_local[M];
  double r_local[N];
  double q_local[N];
#pragma HLS ARRAY_PARTITION variable=s_local cyclic factor=4 dim=1
#pragma HLS ARRAY_PARTITION variable=p_local cyclic factor=4 dim=1

  // Load p into local memory
load_p:
  for (j = 0; j < m; j++) {
#pragma HLS PIPELINE
    p_local[j] = p[j];
  }

  // Init s_local
init_s:
  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE
    s_local[i] = 0;
  }

  // Load r into local memory
load_r:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE
    r_local[i] = r[i];
  }

main_i:
  for (i = 0; i < n; i++)
    {
      double q_acc = 0.0;
      double ri = r_local[i];
    main_j:
      for (j = 0; j < m; j++)
	{
#pragma HLS PIPELINE II=1
	  double a = A[i][j];
	  s_local[j] = s_local[j] + ri * a;
	  q_acc = q_acc + a * p_local[j];
	}
      q_local[i] = q_acc;
    }

  // Write back results
store_s:
  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE
    s[i] = s_local[i];
  }
store_q:
  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE
    q[i] = q_local[i];
