void kernel_covariance(
		       double float_n,
		       double data[ N + 0][M + 0],
		       double cov[ M + 0][M + 0],
		       double mean[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=cov offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=mean offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data bundle=control
#pragma HLS INTERFACE s_axilite port=cov bundle=control
#pragma HLS INTERFACE s_axilite port=mean bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  // Local on-chip buffers to avoid repeated AXI latency
  static double l_data[N][M];
#pragma HLS BIND_STORAGE variable=l_data type=ram_2p impl=bram
  static double l_mean[M];
#pragma HLS BIND_STORAGE variable=l_mean type=ram_2p impl=bram

  // Load data into local buffer; reset mean accumulators
  load_data_i:
  for (i = 0; i < n; i++) {
    load_data_j:
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      l_data[i][j] = data[i][j];
    }
  }

  init_mean:
  for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    l_mean[j] = 0.0;
  }

  // Accumulate mean: inner loop over columns => independent accumulators,
  // no carried dependence on the same address across consecutive iterations.
  mean_outer:
  for (i = 0; i < n; i++) {
    mean_inner:
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=l_mean inter false
      l_mean[j] += l_data[i][j];
    }
  }

  mean_div:
  for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    l_mean[j] /= float_n;
    mean[j] = l_mean[j];
  }

  // Subtract mean from data in local buffer
  sub_outer:
  for (i = 0; i < n; i++) {
    sub_inner:
    for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
      l_data[i][j] -= l_mean[j];
    }
  }

  // Covariance: accumulate over n with row buffer to break the
  // double-add carried dependence by keeping multiple partials.
  cov_outer:
  for (i = 0; i < m; i++) {
    cov_mid:
    for (j = i; j < m; j++) {
      double acc = 0.0;
      cov_inner:
      for (k = 0; k < n; k++) {
#pragma HLS PIPELINE II=1
        acc += l_data[k][i] * l_data[k][j];
      }
      double v = acc / (float_n - 1.0);
      cov[i][j] = v;
      cov[j][i] = v;
    }
  }

}
}
