#pragma HLS PIPELINE II=1
	local_path[i][j] = path[i][j];
      }

  // Floyd-Warshall on local memory. The row path[k][*] is reused across i,
  // so cache it into a small partitioned buffer to remove read pressure.
  for (k = 0; k < n; k++)
    {
