  const int n = N;

  int i, j, k;

  // Partition along the ROW dimension so 8 consecutive i-rows are read
  // in parallel; the inner reduction loops are unrolled by 8 to feed
  // 8 independent FP accumulators (true dependency distance = 8 -> II=1).
  static double A_loc[M][N];
  static double R_loc[N][N];
  static double Q_loc[M][N];
#pragma HLS ARRAY_PARTITION variable=A_loc cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=Q_loc cyclic factor=8 dim=1

