void kernel_nussinov( char seq[ N + 0],
			   int table[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=seq offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=table offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=seq bundle=control
#pragma HLS INTERFACE s_axilite port=table bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

    // Local buffers for fast on-chip access
    char l_seq[N];
    int  l_table[N][N];

    int i, j, k;

    // Load inputs
    for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
        l_seq[i] = seq[i];
    }

    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            l_table[i][j] = table[i][j];
        }
    }

    for (i = n-1; i >= 0; i--) {
        for (j = i+1; j < n; j++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=N

            // Accumulate into a scalar register to break the
            // read-modify-write carried dependence on l_table[i][j].
            int best = l_table[i][j];

            if (j-1 >= 0) {
                int t = l_table[i][j-1];
                best = (best >= t) ? best : t;
            }
            if (i+1 < n) {
                int t = l_table[i+1][j];
                best = (best >= t) ? best : t;
            }

            if (j-1 >= 0 && i+1 < n) {
                int diag = l_table[i+1][j-1];
                if (i < j-1) {
                    int bonus = (((l_seq[i]) + (l_seq[j])) == 3 ? 1 : 0);
                    int t = diag + bonus;
                    best = (best >= t) ? best : t;
                } else {
                    best = (best >= diag) ? best : diag;
                }
            }

            for (k = i+1; k < j; k++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=N
                int t = l_table[i][k] + l_table[k+1][j];
                best = (best >= t) ? best : t;
            }

            l_table[i][j] = best;
        }
    }

    // Store output
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            table[i][j] = l_table[i][j];
