#include "symm.h"

extern "C" {
void kernel_symm(
		 double alpha,
		 double beta,
		 double C[ M + 0][N + 0],
		 double A[ M + 0][M + 0],
		 double B[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int m = M;
    const int n = N;

    int i, j, k;

    // Local on-chip copies to avoid repeated external-memory thrashing.
    static double Cl[M][N];
    static double Al[M][M];
    static double Bl[M][N];
#pragma HLS ARRAY_PARTITION variable=Bl cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=Cl cyclic factor=4 dim=2

    // Load inputs into BRAM.
LOAD_C:
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            Cl[i][j] = C[i][j];
        }
LOAD_A:
    for (i = 0; i < m; i++)
        for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
            Al[i][j] = A[i][j];
        }
LOAD_B:
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            Bl[i][j] = B[i][j];
        }

    // Compute on local buffers.
    // For each i:
    //   pass A: C[k][j] += alpha*B[i][j]*A[i][k]   for k < i
    //   pass B: temp2[j] = sum_{k<i} B[k][j]*A[i][k] ; then update C[i][j]
    // The temp2 accumulation is done with j innermost (vectorizable, no
    // serial double-precision dependency across the reduction).
COMP_I:
    for (i = 0; i < m; i++) {
        double temp2[N];
#pragma HLS ARRAY_PARTITION variable=temp2 cyclic factor=4 dim=1

INIT_T:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            temp2[j] = 0;
        }

COMP_K:
        for (k = 0; k < i; k++) {
            double aik = Al[i][k];
            double aik_a = alpha * aik;
COMP_J:
            for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
                double bij = Bl[i][j];
                double bkj = Bl[k][j];
                Cl[k][j] += aik_a * bij;
                temp2[j] += bkj * aik;   // distinct accumulator per j -> no serial dep
            }
        }

        double aii = Al[i][i];
FIN_J:
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            Cl[i][j] = beta * Cl[i][j]
                       + alpha * Bl[i][j] * aii
                       + alpha * temp2[j];
        }
    }

    // Store result back.
STORE_C:
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            C[i][j] = Cl[i][j];
        }
}
}
