```cpp
#include "trisolv.h"

extern "C" {
void kernel_trisolv(
		    double L[ N + 0][N + 0],
		    double x[ N + 0],
		    double b[ N + 0])
{
#pragma HLS INTERFACE m_axi port=L offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=L bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j;

  // Local buffer for the already-solved x values, so the inner reduction
  // reads from on-chip memory with low latency.
  double x_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=8 dim=1

  // Partial accumulators break the FP-add carried dependence in the
  // inner reduction loop so it can pipeline at low II.
  const int NACC = 8;
  double acc[NACC];
#pragma HLS ARRAY_PARTITION variable=acc complete dim=1

  for (i = 0; i < n; i++)
    {
      double bi = b[i];

      for (int k = 0; k < NACC; k++)
      {
#pragma HLS UNROLL
        acc[k] = 0.0;
      }

      for (j = 0; j < i; j++)
      {
#pragma HLS PIPELINE II=1
        acc[j & (NACC - 1)] += L[i][j] * x_local[j];
      }

      // Reduce partial sums.
      double sum = 0.0;
      for (int k = 0; k < NACC; k++)
      {
#pragma HLS UNROLL
        sum += acc[k];
      }

      double xi = (bi - sum) / L[i][i];
      x_local[i] = xi;
      x[i] = xi;
    }

}
}
